import React, { useEffect, useState } from 'react';
import ClientesCarrusel from '../components/ClientesCarrusel';
import Testimonios from '../components/Testimonios';
import Equipo from '../components/Equipo';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/Inicio.css';
import Hero from '../components/Hero';

const Inicio = () => {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => {
  document.body.style.backgroundImage = "url('/fondo-naranja.png')";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundRepeat = "no-repeat";
    document.body.style.minHeight = "100vh";
    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundRepeat = "";
      document.body.style.minHeight = "";
    };
  }, []);
  return (
    <div className="inicio-container">
      {/* Botón desplegable de menú */}
      <div className="menu-dropdown-container">
        <button className="menu-btn" onClick={() => setMenuOpen(!menuOpen)}>
          Menú
        </button>
        {menuOpen && (
          <div className="menu-dropdown">
            <Link to="/servicios" onClick={() => setMenuOpen(false)}>Servicios</Link>
            <Link to="/sobre-nosotros" onClick={() => setMenuOpen(false)}>Sobre Nosotros</Link>
            <Link to="/contacto" onClick={() => setMenuOpen(false)}>Contacto</Link>
            <Link to="/ubicacion-redes" onClick={() => setMenuOpen(false)}>Ubicación y Redes</Link>
          </div>
        )}
      </div>
      <Hero />
      {/* Carrusel de clientes */}
      <ClientesCarrusel />
      {/* Testimonios */}
      <Testimonios />
      {/* Equipo */}
      <Equipo />
      {/* Pie de página */}
      <footer style={{marginTop: '2.5rem', textAlign: 'center', color: '#000', fontFamily: 'Montserrat, Arial, sans-serif'}}>
        <div>© 2025 PHG Soluciones Contables.</div>
      </footer>
    </div>
  );
};

export default Inicio;
